        self.assertEqual(N.ramas_vivas({"cola": "cola-oracle-20261018-231246.json"},
                                       {"rama": rama}, False), set())
        self.assertEqual(N.ramas_vivas({"cola": "otra.txt"}, {"no": "rama"}, True), set())

